{
  "measurement_needs": [
    "Bond strength (e.g., shear or microtensile) between resin cement and zirconia",
    "Failure mode analysis of the fractured interface"
  ],
  "objective_met": true,
  "recommendations": [
    {
      "instrument_id": "EQ15",
      "role": "primary",
      "technique": "Mechanical testing (shear or tensile bond strength)",
      "why": "A universal testing machine can apply controlled force to detach the cement from the zirconia, measuring the maximum load at failure to calculate the bond strength.",
      "accessories_to_confirm": [
        "Appropriate load cell",
        "Shear testing fixture (e.g., notched edge or wire loop) or microtensile grips"
      ]
    },
    {
      "instrument_id": "EQ14",
      "role": "supplementary",
      "technique": "Stereomicroscopy",
      "why": "Provides a quick, low-magnification optical inspection of the fracture surfaces after testing to assess whether the failure was adhesive (at the interface) or cohesive (within the cement).",
      "accessories_to_confirm": []
    },
    {
      "instrument_id": "EQ10",
      "role": "supplementary",
      "technique": "Scanning electron microscopy (SEM)",
      "why": "Useful for high-resolution examination of the fractured surfaces after testing to determine the exact failure mode and evaluate the cement-zirconia interface.",
      "accessories_to_confirm": []
    }
  ],
  "not_available": [],
  "clarifying_question": null,
  "summary": "To measure how strongly the cement holds onto the zirconia, you will need to perform a mechanical test, such as a shear or microtensile bond strength test. The Instron universal testing system can apply the necessary force and measure the load at failure. Afterward, you can use a stereomicroscope or scanning electron microscope to examine the fracture surfaces and determine exactly where the bond failed."
}

{
  "measurement_needs": [
    "High-resolution imaging of cell morphology (flattening vs. rounding)",
    "Imaging from above (top-down) due to the opaque nature of the titanium substrate"
  ],
  "objective_met": true,
  "recommendations": [
    {
      "instrument_id": "EQ10",
      "role": "primary",
      "technique": "Scanning Electron Microscopy (SEM)",
      "why": "SEM provides extremely high-resolution, 3D-like images of cell surfaces. It is the gold standard for evaluating cell morphology, attachment, and spreading on opaque metallic substrates like titanium.",
      "accessories_to_confirm": [
        "Critical point dryer and sputter coater for sample preparation (if not imaging in environmental mode)"
      ]
    },
    {
      "instrument_id": "EQ08",
      "role": "primary",
      "technique": "Upright Confocal Microscopy",
      "why": "Because titanium is opaque, you cannot use standard inverted microscopes. An upright confocal microscope can image fluorescently stained cells (e.g., actin and nuclei) from above to clearly visualize their spreading and cytoskeletal structure.",
      "accessories_to_confirm": [
        "Water-dipping or long-working-distance objectives (if imaging in liquid media)",
        "Appropriate laser lines and filters for your chosen fluorophores"
      ]
    },
    {
      "instrument_id": "EQ12",
      "role": "supplementary",
      "technique": "Epifluorescence Microscopy",
      "why": "This upright microscope can be used for basic fluorescence imaging of stained cells from above, though it lacks the optical sectioning and high resolution of a confocal microscope.",
      "accessories_to_confirm": [
        "Appropriate fluorescence filter cubes",
        "Reflected light (epi-illumination) capability"
      ]
    }
  ],
  "not_available": [],
  "clarifying_question": null,
  "summary": "To observe cell morphology on an opaque titanium disc, you must use techniques that image the sample from above rather than below. Scanning electron microscopy (SEM) is an excellent choice for high-resolution surface imaging of cell spreading. Alternatively, if you fluorescently stain the cells, an upright confocal or epifluorescence microscope can visualize their shape and cytoskeletal structure."
}

{
  "measurement_needs": [
    "Compressive modulus (stiffness) of macroscopic bone samples"
  ],
  "objective_met": true,
  "recommendations": [
    {
      "instrument_id": "EQ15",
      "role": "primary",
      "technique": "Uniaxial compression testing",
      "why": "A universal testing machine can apply controlled compressive loads to the bone cubes and measure the resulting displacement to calculate the compressive modulus.",
      "accessories_to_confirm": [
        "Compression platens",
        "Load cell with an appropriate force capacity for trabecular bone"
      ]
    }
  ],
  "not_available": [
    {
      "technique": "Micro-computed tomography (micro-CT)",
      "why_useful": "Useful for measuring the porosity and trabecular architecture of the bone cubes, which strongly influences their apparent compressive modulus."
    }
  ],
  "clarifying_question": null,
  "summary": "The Instron universal testing system can perform the compression tests needed to determine the compressive modulus of your bone cubes. You will need to ensure the system is equipped with flat compression platens and a load cell rated for the expected forces. While not available on this list, micro-CT would be a valuable complementary technique to correlate the mechanical properties with the bone's internal structure."
}

